import pathlib
PATCH = {
    'src/main/java/com/example/fpvdrone/event/ClientEvents.java': 'package com.example.fpvdrone.event;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.client.ClientDroneState;\nimport com.example.fpvdrone.client.gui.FpvHudOverlay;\nimport com.example.fpvdrone.client.renderer.FpvDroneRenderer;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.network.C2SDroneControlPacket;\nimport com.example.fpvdrone.network.PacketHandler;\nimport com.example.fpvdrone.registry.ModEntities;\nimport net.minecraft.client.Minecraft;\nimport net.minecraft.client.player.Input;\nimport net.minecraft.util.Mth;\nimport net.minecraftforge.api.distmarker.Dist;\nimport net.minecraftforge.client.event.ClientPlayerNetworkEvent;\nimport net.minecraftforge.client.event.EntityRenderersEvent;\nimport net.minecraftforge.client.event.MovementInputUpdateEvent;\nimport net.minecraftforge.client.event.RegisterGuiOverlaysEvent;\nimport net.minecraftforge.client.event.RenderGuiOverlayEvent;\nimport net.minecraftforge.client.event.RenderHandEvent;\nimport net.minecraftforge.client.event.ViewportEvent;\nimport net.minecraftforge.event.TickEvent;\nimport net.minecraftforge.eventbus.api.SubscribeEvent;\nimport net.minecraftforge.fml.common.Mod;\nimport org.joml.Quaternionf;\nimport org.joml.Vector3f;\nimport org.lwjgl.glfw.GLFW;\n\n@Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, value = Dist.CLIENT, bus = Mod.EventBusSubscriber.Bus.FORGE)\npublic class ClientEvents {\n    private static double lastMouseX = Double.NaN;\n\n    @SubscribeEvent\n    public static void onClientTick(TickEvent.ClientTickEvent event) {\n        if (event.phase != TickEvent.Phase.END) {\n            return;\n        }\n        ClientDroneState.tick();\n\n        Minecraft mc = Minecraft.getInstance();\n        if (!ClientDroneState.isPiloting() || mc.player == null || mc.screen != null) {\n            lastMouseX = Double.NaN;\n            return;\n        }\n\n        long window = mc.getWindow().getWindow();\n        float pitchInput = 0.0F;\n        if (mc.options.keyUp.isDown()) {\n            pitchInput -= 1.0F; // W: nose down\n        }\n        if (mc.options.keyDown.isDown()) {\n            pitchInput += 1.0F; // S: nose up\n        }\n\n        float rollInput = 0.0F;\n        if (mc.options.keyLeft.isDown()) {\n            rollInput -= 1.0F; // A: bank left\n        }\n        if (mc.options.keyRight.isDown()) {\n            rollInput += 1.0F; // D: bank right\n        }\n\n        float throttleDelta = 0.0F;\n        if (mc.options.keyJump.isDown()) {\n            throttleDelta += 1.0F; // Space: throttle up\n        }\n        if (GLFW.glfwGetKey(window, GLFW.GLFW_KEY_LEFT_SHIFT) == GLFW.GLFW_PRESS) {\n            throttleDelta -= 1.0F; // Left Shift: throttle down\n        }\n\n        float yawInput = 0.0F;\n        if (GLFW.glfwGetKey(window, GLFW.GLFW_KEY_LEFT) == GLFW.GLFW_PRESS) {\n            yawInput -= 1.0F;\n        }\n        if (GLFW.glfwGetKey(window, GLFW.GLFW_KEY_RIGHT) == GLFW.GLFW_PRESS) {\n            yawInput += 1.0F;\n        }\n\n        double currentMouseX = mc.mouseHandler.xpos();\n        if (!Double.isNaN(lastMouseX)) {\n            double dx = currentMouseX - lastMouseX;\n            yawInput = Mth.clamp(yawInput + (float) (dx * 0.025D), -1.0F, 1.0F);\n        }\n        lastMouseX = currentMouseX;\n\n        PacketHandler.sendToServer(new C2SDroneControlPacket(\n                ClientDroneState.getActiveDroneId(),\n                pitchInput,\n                rollInput,\n                yawInput,\n                throttleDelta\n        ));\n    }\n\n    @SubscribeEvent\n    public static void onMovementInputUpdate(MovementInputUpdateEvent event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            Input input = event.getInput();\n            input.forwardImpulse = 0.0F;\n            input.leftImpulse = 0.0F;\n            input.up = false;\n            input.down = false;\n            input.left = false;\n            input.right = false;\n            input.jumping = false;\n            input.shiftKeyDown = false;\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderHand(RenderHandEvent event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            event.setCanceled(true);\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderGuiOverlayPre(RenderGuiOverlayEvent.Pre event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            if (!event.getOverlay().id().getNamespace().equals(FpvDroneMod.MODID)) {\n                event.setCanceled(true);\n            }\n        }\n    }\n\n    @SubscribeEvent\n    public static void onComputeCameraAngles(ViewportEvent.ComputeCameraAngles event) {\n        if (ClientDroneState.getPhase() == ClientDroneState.Phase.FREEZE_FRAME) {\n            event.setYaw(ClientDroneState.getLastCamYaw());\n            event.setPitch(ClientDroneState.getLastCamPitch());\n            event.setRoll(ClientDroneState.getLastCamRoll());\n            return;\n        }\n\n        if (!ClientDroneState.isPiloting()) {\n            return;\n        }\n\n        Minecraft mc = Minecraft.getInstance();\n        if (mc.getCameraEntity() instanceof FpvDroneEntity drone) {\n            Quaternionf q = drone.getInterpolatedOrientation((float) event.getPartialTick());\n            Vector3f forward = new Vector3f(0.0F, 0.0F, 1.0F).rotate(q);\n            Vector3f localUp = new Vector3f(0.0F, 1.0F, 0.0F).rotate(q);\n            Vector3f localRight = new Vector3f(-1.0F, 0.0F, 0.0F).rotate(q);\n\n            float yaw = (float) Math.toDegrees(Math.atan2(-forward.x, forward.z));\n            float pitch = (float) -Math.toDegrees(Math.asin(Mth.clamp(forward.y, -1.0F, 1.0F)));\n\n            Vector3f worldUp = new Vector3f(0.0F, 1.0F, 0.0F);\n            Vector3f horizonRight = new Vector3f(forward).cross(worldUp);\n            float roll = 0.0F;\n            if (horizonRight.lengthSquared() > 1.0E-5F) {\n                horizonRight.normalize();\n                Vector3f horizonUp = new Vector3f(horizonRight).cross(forward).normalize();\n                roll = (float) Math.toDegrees(Math.atan2(localRight.dot(horizonUp), localRight.dot(horizonRight)));\n            } else {\n                roll = (float) Math.toDegrees(Math.atan2(localUp.x, localUp.z));\n            }\n\n            ClientDroneState.setLastCamAngles(yaw, pitch, roll);\n            event.setYaw(yaw);\n            event.setPitch(pitch);\n            event.setRoll(roll);\n        }\n    }\n\n    @SubscribeEvent\n    public static void onClientLogout(ClientPlayerNetworkEvent.LoggingOut event) {\n        ClientDroneState.resetImmediate();\n    }\n\n    @Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, value = Dist.CLIENT, bus = Mod.EventBusSubscriber.Bus.MOD)\n    public static class ClientModEvents {\n        @SubscribeEvent\n        public static void onRegisterRenderers(EntityRenderersEvent.RegisterRenderers event) {\n            event.registerEntityRenderer(ModEntities.FPV_DRONE.get(), FpvDroneRenderer::new);\n        }\n\n        @SubscribeEvent\n        public static void onRegisterGuiOverlays(RegisterGuiOverlaysEvent event) {\n            event.registerAboveAll("fpv_hud", FpvHudOverlay.HUD_OVERLAY);\n        }\n    }\n}\n',
    'generate_assets.py': 'import os\nimport math\nimport struct\nimport wave\nimport subprocess\nfrom pathlib import Path\nfrom PIL import Image, ImageDraw\n\nBASE = Path(".")\nASSETS = BASE / "src/main/resources/assets/fpvdrone"\n\nfor sub in [\n    "textures/entity",\n    "textures/item",\n    "textures/models/armor",\n    "sounds",\n    "geo",\n    "animations",\n    "lang",\n    "models/item",\n]:\n    (ASSETS / sub).mkdir(parents=True, exist_ok=True)\n\n\ndef make_drone_texture(path: Path):\n    img = Image.new("RGBA", (128, 128), (28, 30, 34, 255))\n    draw = ImageDraw.Draw(img)\n    for y in range(0, 128, 4):\n        for x in range(0, 128, 4):\n            c = 38 if ((x // 4 + y // 4) % 2 == 0) else 24\n            draw.rectangle([x, y, x + 3, y + 3], fill=(c, c + 2, c + 5, 255))\n    draw.rectangle([64, 0, 127, 63], fill=(68, 78, 46, 255))\n    draw.rectangle([64, 20, 127, 26], fill=(195, 165, 55, 255))\n    draw.rectangle([64, 48, 127, 63], fill=(95, 98, 102, 255))\n    draw.rectangle([0, 64, 63, 127], fill=(18, 20, 24, 255))\n    draw.ellipse([12, 76, 52, 116], fill=(10, 35, 65, 255), outline=(90, 100, 115, 255), width=2)\n    draw.ellipse([22, 86, 36, 100], fill=(70, 170, 230, 255))\n    draw.rectangle([64, 64, 127, 127], fill=(42, 44, 48, 255))\n    draw.rectangle([64, 96, 127, 127], fill=(190, 50, 35, 255))\n    img.save(path)\n\n\ndef make_drone_item_texture(path: Path):\n    img = Image.new("RGBA", (128, 128), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(img)\n    draw.line([(20, 20), (108, 108)], fill=(45, 48, 54, 255), width=10)\n    draw.line([(108, 20), (20, 108)], fill=(45, 48, 54, 255), width=10)\n    for cx, cy in [(22, 22), (106, 22), (22, 106), (106, 106)]:\n        draw.ellipse([cx - 18, cy - 18, cx + 18, cy + 18], outline=(210, 60, 40, 220), width=4)\n        draw.ellipse([cx - 6, cy - 6, cx + 6, cy + 6], fill=(160, 165, 175, 255))\n    draw.rectangle([48, 40, 80, 88], fill=(32, 34, 38, 255), outline=(90, 95, 105, 255), width=2)\n    draw.rectangle([54, 28, 74, 50], fill=(72, 84, 48, 255))\n    draw.rectangle([58, 22, 70, 28], fill=(200, 165, 50, 255))\n    img.save(path)\n\n\ndef make_goggles_item_texture(path: Path):\n    img = Image.new("RGBA", (128, 128), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(img)\n    draw.rectangle([10, 48, 118, 76], fill=(35, 38, 42, 255))\n    draw.rounded_rectangle([20, 36, 108, 92], radius=12, fill=(52, 56, 62, 255), outline=(110, 118, 128, 255), width=3)\n    draw.rounded_rectangle([28, 48, 58, 80], radius=6, fill=(15, 45, 75, 255), outline=(0, 210, 180, 255), width=2)\n    draw.rounded_rectangle([70, 48, 100, 80], radius=6, fill=(15, 45, 75, 255), outline=(0, 210, 180, 255), width=2)\n    draw.rectangle([28, 14, 34, 36], fill=(25, 25, 28, 255))\n    draw.ellipse([25, 8, 37, 20], fill=(210, 55, 40, 255))\n    draw.rectangle([94, 18, 100, 36], fill=(25, 25, 28, 255))\n    img.save(path)\n\n\ndef make_goggles_armor_layer(path: Path):\n    # Sleek eye-level FPV goggles only (128x64 armor UV: head front is u=16..32, v=16..32; eyes at v=22..26)\n    img = Image.new("RGBA", (128, 64), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(img)\n    # Thin elastic strap around sides and back of head (u=0..15, 32..63)\n    draw.rectangle([0, 22, 15, 25], fill=(32, 34, 38, 255))\n    draw.rectangle([32, 22, 63, 25], fill=(32, 34, 38, 255))\n    # Compact front goggle frame strictly over eye zone (u=16..31, v=21..26)\n    draw.rectangle([16, 21, 31, 26], fill=(45, 48, 54, 255))\n    # Dual dark-cyan FPV lenses\n    draw.rectangle([18, 22, 22, 25], fill=(0, 195, 170, 255))\n    draw.rectangle([25, 22, 29, 25], fill=(0, 195, 170, 255))\n    img.save(path)\n\n\ndef write_wav_and_convert_ogg(wav_path: Path, ogg_path: Path, sample_rate: int, samples):\n    with wave.open(str(wav_path), "w") as wf:\n        wf.setnchannels(2)\n        wf.setsampwidth(2)\n        wf.setframerate(sample_rate)\n        frames = bytearray()\n        for l, r in samples:\n            li = max(-32767, min(32767, int(l * 32767)))\n            ri = max(-32767, min(32767, int(r * 32767)))\n            frames.extend(struct.pack("<hh", li, ri))\n        wf.writeframes(bytes(frames))\n    subprocess.run(\n        ["ffmpeg", "-y", "-i", str(wav_path), "-c:a", "libvorbis", "-q:a", "6", str(ogg_path)],\n        check=True,\n        stdout=subprocess.DEVNULL,\n        stderr=subprocess.DEVNULL,\n    )\n    wav_path.unlink()\n\n\ndef generate_sounds():\n    sr = 44100\n    n1 = sr * 2\n    s1 = []\n    for i in range(n1):\n        t = i / sr\n        v = (\n            0.35 * math.sin(2 * math.pi * 180.0 * t)\n            + 0.25 * math.sin(2 * math.pi * 360.0 * t)\n            + 0.15 * math.sin(2 * math.pi * 540.0 * t)\n            + 0.08 * math.sin(2 * math.pi * 720.0 * t)\n        )\n        s1.append((v, v))\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp1.wav", ASSETS / "sounds/drone_motor_loop.ogg", sr, s1)\n\n    n2 = int(sr * 0.45)\n    s2 = []\n    for i in range(n2):\n        t = i / sr\n        freq = 1200.0 if t < 0.12 else (1600.0 if t < 0.24 else 2200.0)\n        env = 1.0 if (t % 0.14) < 0.10 else 0.0\n        v = 0.5 * env * math.sin(2 * math.pi * freq * t)\n        s2.append((v, v))\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp2.wav", ASSETS / "sounds/drone_arm_beep.ogg", sr, s2)\n\n    import random\n    rng = random.Random(42)\n    n3 = int(sr * 1.5)\n    s3 = [(rng.uniform(-0.35, 0.35), rng.uniform(-0.35, 0.35)) for _ in range(n3)]\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp3.wav", ASSETS / "sounds/signal_static_loop.ogg", sr, s3)\n\n    n4 = sr\n    s4 = []\n    for i in range(n4):\n        t = i / sr\n        env = math.exp(-4.5 * t)\n        boom = math.sin(2 * math.pi * (90.0 * math.exp(-3.0 * t) + 28.0) * t)\n        noise = rng.uniform(-0.6, 0.6) * math.exp(-7.0 * t)\n        v = max(-1.0, min(1.0, env * (0.75 * boom + noise)))\n        s4.append((v, v))\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp4.wav", ASSETS / "sounds/drone_explosion.ogg", sr, s4)\n\n\nif __name__ == "__main__":\n    make_drone_texture(ASSETS / "textures/entity/fpv_drone.png")\n    make_drone_item_texture(ASSETS / "textures/item/fpv_drone_item.png")\n    make_goggles_item_texture(ASSETS / "textures/item/fpv_goggles.png")\n    make_goggles_armor_layer(ASSETS / "textures/models/armor/fpv_goggles_layer_1.png")\n    generate_sounds()\n    print("Assets generated successfully.")\n',
}
for k, v in PATCH.items():
    p = pathlib.Path(k)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(v, encoding="utf-8")
print("Patched", len(PATCH), "files")
